const s=require('../../../../miniprogram/utils/service'),d=require('../../../../miniprogram/utils/domain');Page({data:{week:d.weekKey(),busy:false,error:'',items:[],missingRecipes:[],missingPrices:0,total:0,role:'',plan:null,editing:null},onShow(){this.load();},async load(){await s.run(this,async()=>{const c=await s.call();if(c.unbound)throw Error('先创建或加入家庭');const plan=c.state.plans[this.data.week];const out=d.shopping(c.state,plan);this.setData({...out,plan:plan||null,role:c.role});});},onPullDownRefresh(){this.load().finally(()=>wx.stopPullDownRefresh());},changeWeek(e){this.setData({week:e.detail.value});this.load();},async check(e){await s.run(this,async()=>{const x=this.data.items.find(i=>i.key===e.currentTarget.dataset.key);await s.call('check',{week:this.data.week,version:this.data.plan.version,key:x.key,checked:!x.checked});});await this.load();},edit(e){const x=this.data.items.find(i=>i.key===e.currentTarget.dataset.key);this.setData({editing:{...x,price:x.price==null?'':String(x.price)}});},field(e){this.setData({editing:{...this.data.editing,[e.currentTarget.dataset.key]:e.detail.value}});},cancel(){this.setData({editing:null});},async save(){let ok=false;await s.run(this,async()=>{await s.call('supply',this.data.editing);this.setData({editing:null});ok=true;});if(ok)await this.load();},menu(){wx.switchTab({url:'/pages/menu/index'});}});